// [Blur2PC][macOS] Original upper sampler defaults, verified by real Metal sampling.
#include <display.h>
#include <cstring>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
static void require(bool value,const char* why){if(!value){std::cerr<<why<<std::endl;throw std::runtime_error(why);}}
static std::vector<U8> blob(bool vertex){
    const std::string bindings=vertex?"\"ubos\":[]":"\"ubos\":[{\"binding\":0,\"block_size\":16,\"name\":\"Constants\"}],\"textures\":[{\"binding\":0,\"type\":\"texture2D\"}]";
    const std::string metadata=std::string("{\"parameters\":{},\"input_semantics\":")+(vertex?"[[0,0,0]]":"[]")+",\"reflection\":{"+bindings+"}}";
    const std::string source=std::string("#include <metal_stdlib>\nusing namespace metal;\n")+(vertex?"struct I{float2 p[[attribute(0)]];};vertex float4 blur_main(I i[[stage_in]]){return float4(i.p,.5,1);}":"fragment float4 blur_main(constant float4& c[[buffer(0)]],texture2d<float> t[[texture(0)]],sampler s[[sampler(0)]]){return t.sample(s,c.xy,level(c.z));}");
    const std::string entry="blur_main";std::vector<U8> b(40);std::memcpy(b.data(),"BMSL",4);auto word=[&](U32 p,U32 n){for(U32 i=0;i<4;++i)b[p+i]=U8(n>>(8*i));};word(4,1);word(8,vertex?0:1);word(16,40);word(20,metadata.size());word(24,40+metadata.size());word(28,source.size());word(32,40+metadata.size()+source.size());word(36,entry.size());b.insert(b.end(),metadata.begin(),metadata.end());b.insert(b.end(),source.begin(),source.end());b.insert(b.end(),entry.begin(),entry.end());word(12,b.size());return b;
}
static void pixels(Display2::C_Surface& target,U32 expected,U32 tolerance=0){auto lock=target.LockRect(16);require(lock.pBits,"Upper sampler GPU readback unavailable");bool correct=true;for(U32 y=0;y<target.GetHeight();++y)for(U32 x=0;x<target.GetWidth();++x){U32 actual;std::memcpy(&actual,lock.pBits+y*lock.pitch+x*4,4);for(U32 c=0;c<4;++c){const int a=(actual>>(c*8))&255,e=(expected>>(c*8))&255;correct&=std::abs(a-e)<=int(tolerance);}}target.UnlockRect();require(correct,"Upper sampler default/address/filter differs from actual expected GPU pixels");}
template<class F>static void rejects(F call){bool failed=false;try{call();}catch(const std::logic_error&){failed=true;}require(failed,"Invalid upper sampler request was accepted");}
int main(){try{
    using namespace Display;C_Device device;C_DeviceParams params;params.m_Width=19;params.m_Height=11;require(device.Create(params)&&device.CreateVolatile(params),"Upper sampler native device failed");auto& native=device.GetDisplay2();auto& c=native.GetContext();
    Display2::C_VertexShader vs;Display2::C_PixelShader ps;auto v=blob(true),p=blob(false);std::string error;require(native.CreateVertexShader(v.size(),v.data(),0,&vs,nullptr,&error),error.c_str());require(native.CreatePixelShader(p.size(),p.data(),0,&ps,nullptr,&error),error.c_str());Display2::C_VertexDeclaration declaration;Display2::C_VertexFormat format;format.AddElement(0,0,Display2::E_VertexElementType_F32_2,Display2::E_VertexElementUsage_Position,0);Display2::C_VertexBuffer vertices;require(native.CreateVertexDeclaration(format,&declaration)&&native.CreateVertexBuffer(32,0,&vertices),"Upper sampler real geometry failed");const F32 quad[]={-1,1,1,1,-1,-1,1,-1};auto out=vertices.Lock();require(out,"Upper sampler geometry map failed");std::memcpy(out,quad,sizeof(quad));vertices.Unlock();Display2::C_Texture texture;require(native.CreateTexture2D(2,2,2,0,Display2::E_TextureFormat_A8R8G8B8,&texture),"Upper sampler authored mip texture failed");auto lock=texture.LockRect2D(0);require(lock.pBits,"Upper sampler base upload failed");const U32 colours[]={0xffff0000,0xff00ff00,0xff0000ff,0xffffffff};std::memcpy(lock.pBits,colours,8);std::memcpy(lock.pBits+lock.pitch,colours+2,8);texture.UnlockRect2D(0);lock=texture.LockRect2D(1);require(lock.pBits,"Upper sampler mip upload failed");const U32 mip=0xff00ffff;std::memcpy(lock.pBits,&mip,4);texture.UnlockRect2D(1);c.SetVertexShader(&vs);c.SetPixelShader(&ps);c.SetVertexBuffer(0,&vertices,0,8,&declaration);c.SetTexture(0,&texture);device.SetDepthEnable(E_Bool_False);device.SetCullMode(E_CullMode_None);device.SetBlendEnable(E_Bool_False);device.SetAlphaTestEnable(E_Bool_False);device.SetColourWriteEnable(E_ColourWriteEnable_All);
    auto draw=[&](F32 u,F32 v,F32 lod,U32 expected,U32 tolerance=0){const F32 constants[]={u,v,lod,0};c.SetPixelShaderConstantF(0,constants,1);c.BeginScene();c.Clear(Display2::E_Clear_Colour,0xff102030);c.DrawPrimitive(Display2::E_PrimitiveType_TriangleStrip,0,4);c.EndScene();pixels(*device.GetNativeColourSurface(),expected,tolerance);};
    device.SetTextureFilterMagMinMip(0,E_TextureFilter_Point,E_TextureFilter_Point,E_TextureFilter_None);
    for(auto mode:{E_TextureAddress_Wrap,E_TextureAddress_Mirror,E_TextureAddress_Clamp,E_TextureAddress_Border,E_TextureAddress_Default}){device.SetTextureAddress(0,mode);device.SetTextureBorderColour(0,0xffffffff);draw(1.25f,.25f,0,mode==E_TextureAddress_Border?0xffffffff:mode==E_TextureAddress_Clamp||mode==E_TextureAddress_Mirror?0xff00ff00:0xffff0000);}
    device.SetTextureAddressUVW(0,E_TextureAddress_Default,E_TextureAddress_Clamp,E_TextureAddress_Default);const auto mixed=c.GetSamplerState(0);require(mixed.m_TextureAddressU==Display2::E_TextureAddress_Wrap&&mixed.m_TextureAddressV==Display2::E_TextureAddress_Clamp&&mixed.m_TextureAddressW==Display2::E_TextureAddress_Wrap,"Mixed address defaults did not resolve independently");draw(1.25f,1.25f,0,0xff0000ff);
    device.SetTextureAddress(0,E_TextureAddress_Default);device.SetTextureFilterMagMinMip(0,E_TextureFilter_Point,E_TextureFilter_Point,E_TextureFilter_Point);draw(.5f,.5f,1,mip);device.SetTextureFilter(0,E_TextureFilter_Default);const auto defaults=c.GetSamplerState(0);require(defaults.m_TextureFilterMag==Display2::E_TextureFilter_Linear&&defaults.m_TextureFilterMin==Display2::E_TextureFilter_Linear&&defaults.m_TextureFilterMip==Display2::E_TextureFilter_None,"Original distinct mag/min/mip defaults were not restored");draw(.5f,.5f,1,0xff808080,1);
    device.SetTextureFilterMagMinMip(0,E_TextureFilter_Default,E_TextureFilter_Point,E_TextureFilter_Default);require(c.GetSamplerState(0).m_TextureFilterMag==Display2::E_TextureFilter_Linear&&c.GetSamplerState(0).m_TextureFilterMin==Display2::E_TextureFilter_Point&&c.GetSamplerState(0).m_TextureFilterMip==Display2::E_TextureFilter_None,"Mixed filter defaults did not resolve independently");
    const auto untouched=c.GetSamplerState(0);device.SetTextureAddress(E_Sampler_Count-1,E_TextureAddress_Clamp);device.SetTextureFilter(E_Sampler_Count-1,E_TextureFilter_Point);device.SetTextureAddress(E_Sampler_Count-1,E_TextureAddress_Default);device.SetTextureFilter(E_Sampler_Count-1,E_TextureFilter_Default);require(c.GetSamplerState(E_Sampler_Count-1).m_TextureAddressW==Display2::E_TextureAddress_Wrap&&c.GetSamplerState(E_Sampler_Count-1).m_TextureFilterMip==Display2::E_TextureFilter_None&&c.GetSamplerState(0).IsSame(untouched),"Last sampler/default update corrupted another slot");
    for(auto invalid:{E_TextureAddress_Unknown,E_TextureAddress(0),E_TextureAddress(5)}){const auto before=c.GetSamplerState(0);rejects([&]{device.SetTextureAddressUVW(0,E_TextureAddress_Default,invalid,E_TextureAddress_Clamp);});require(c.GetSamplerState(0).IsSame(before),"Invalid address partially changed native sampler state");}for(auto invalid:{E_TextureFilter_Unknown,E_TextureFilter_Count}){const auto before=c.GetSamplerState(0);rejects([&]{device.SetTextureFilterMagMinMip(0,E_TextureFilter_Default,invalid,E_TextureFilter_Point);});require(c.GetSamplerState(0).IsSame(before),"Invalid filter partially changed native sampler state");}rejects([&]{device.SetTextureAddress(E_Sampler_Count,E_TextureAddress_Default);});rejects([&]{device.SetTextureFilter(E_Sampler_Count,E_TextureFilter_Default);});
    c.SetTexture(0,nullptr);native.Destroy(&texture);native.Destroy(&vertices);native.Destroy(&declaration);native.Destroy(&vs);native.Destroy(&ps);require(native.WaitIdle(),"Upper sampler GPU completion failed");device.DestroyVolatile();device.Destroy();std::cout<<"Original upper sampler defaults: real Wrap/Mirror/Clamp/Border/default GPU samples, per-axis mixed restoration, Linear/Linear/None filtering with genuine bilinear/base-mip GPU pixels, explicit mip control, last-slot isolation and transactional unknown/invalid/range rejection PASS\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
